+<body>
+  <div class="app">
+    <header>
+      <div class="brand">
+        <div class="mark" aria-hidden="true">
+          <svg viewBox="0 0 32 32" role="img">
+            <path d="M16 2 7 16l9 5 9-5L16 2Z" fill="#8ab4ff"/>
+            <path d="M7 17.8 16 30l9-12.2-9 5.1-9-5.1Z" fill="#79f2c0"/>
+            <path d="M16 2v19l9-5L16 2Z" fill="#d7def2" opacity=".45"/>
+          </svg>
+        </div>
+        <div>
+          <h1>CodexMint 10K Pixel NFT</h1>
+          <p class="sub">100 x 100 canvas equals 10,000 pixels. Click generate to create a new Ethereum-themed NFT draft.</p>
+        </div>
+      </div>
+      <div class="chain-pill"><span class="dot"></span><span id="chainStatus">Ethereum network ready</span></div>
+    </header>
+
+    <main>
+      <section class="stage" aria-label="Generated NFT preview">
+        <div class="canvas-wrap">
+          <canvas id="nftCanvas" width="100" height="100"></canvas>
+        </div>
+        <div class="token-strip">
+          <p class="token-name" id="tokenName">CodexMint Pixel #0000</p>
+          <span class="token-id" id="tokenId">Token 0 / 10000</span>
+        </div>
+      </section>
+
+      <aside class="panel" aria-label="Generator controls and metadata">
+        <section class="panel-section">
+          <div class="controls">
+            <button class="primary" id="generateBtn">Generate NFT</button>
+            <button id="connectBtn">Connect Wallet</button>
+            <button id="downloadBtn">Download PNG</button>
+          </div>
+          <div class="field">
+            <label for="seedInput">Seed</label>
+            <input id="seedInput" autocomplete="off" placeholder="Random seed or type your own" />
+          </div>
+        </section>
+
+        <section class="panel-section">
+          <div class="stats">
+            <div class="stat"><b id="supplyStat">10,000</b><span>Collection size</span></div>
+            <div class="stat"><b id="pixelStat">10,000</b><span>Pixels per NFT</span></div>
+            <div class="stat"><b id="chainStat">ETH</b><span>Network theme</span></div>
+          </div>
+        </section>
+
+        <section class="panel-section">
+          <div class="traits" id="traits"></div>
+        </section>
+
+        <section class="panel-section">
+          <pre id="metadata"></pre>
+        </section>
+
+        <section class="panel-section">
+          <div class="status" id="status">
+            This is a local generator. It creates NFT art and metadata drafts, but does not mint or sign transactions.
+          </div>
+        </section>
+      </aside>
+    </main>
+  </div>
+
+  <script>
+    const canvas = document.getElementById("nftCanvas");
+    const ctx = canvas.getContext("2d");
+    const generateBtn = document.getElementById("generateBtn");
+    const connectBtn = document.getElementById("connectBtn");
+    const downloadBtn = document.getElementById("downloadBtn");
+    const seedInput = document.getElementById("seedInput");
+    const tokenName = document.getElementById("tokenName");
+    const tokenId = document.getElementById("tokenId");
+    const traitsEl = document.getElementById("traits");
+    const metadataEl = document.getElementById("metadata");
+    const statusEl = document.getElementById("status");
+    const chainStatus = document.getElementById("chainStatus");
+
+    const collectionSize = 10000;
+    const palettes = [
+      { name: "Validator Mint", bg: "#0a1020", grid: "#13213d", main: "#79f2c0", shade: "#2a8f84", light: "#dfffee", accent: "#8ab4ff" },
+      { name: "Gas Aurora", bg: "#110b1d", grid: "#24183a", main: "#c084fc", shade: "#6d28d9", light: "#f5e8ff", accent: "#79f2c0" },
+      { name: "Mainnet Steel", bg: "#0b0f18", grid: "#1c2638", main: "#8ab4ff", shade: "#315aa5", light: "#e7f0ff", accent: "#ffd166" },
+      { name: "Block Fire", bg: "#160b0c", grid: "#311316", main: "#ff8a5c", shade: "#b84328", light: "#ffe9dc", accent: "#ffd166" },
+      { name: "Zero Knowledge", bg: "#071014", grid: "#102026", main: "#69e4ff", shade: "#1b7890", light: "#dcfbff", accent: "#f8f7ff" }
+    ];
+
+    const backgrounds = ["Hash Grid", "Beacon Fog", "Mempool Rain", "L2 Rings", "Archive Noise"];
+    const cores = ["Classic Diamond", "Split Shard", "Staked Prism", "Forked Crystal", "Genesis Rune"];
+    const auras = ["Soft Glow", "Sharp Halo", "Gas Pulse", "Validator Ring", "None"];
+    const rarities = ["Common", "Common", "Uncommon", "Rare", "Epic", "Legendary"];
+
+    let currentMetadata = null;
+
+    function hashString(input) {
+      let h = 2166136261;
+      for (let i = 0; i < input.length; i += 1) {
+        h ^= input.charCodeAt(i);
+        h = Math.imul(h, 16777619);
+      }
+      return h >>> 0;
+    }
+
+    function mulberry32(seed) {
+      return function random() {
+        let t = seed += 0x6D2B79F5;
+        t = Math.imul(t ^ (t >>> 15), t | 1);
+        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
+        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+      };
+    }
+
+    function pick(list, random) {
+      return list[Math.floor(random() * list.length)];
+    }
+
+    function drawPixelRect(x, y, w, h, color) {
+      ctx.fillStyle = color;
+      ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
+    }
+
+    function drawBackground(random, palette, style) {
+      ctx.fillStyle = palette.bg;
+      ctx.fillRect(0, 0, 100, 100);
+
+      if (style === "Hash Grid") {
+        for (let i = 0; i <= 100; i += 10) {
+          drawPixelRect(i, 0, 1, 100, palette.grid);
+          drawPixelRect(0, i, 100, 1, palette.grid);
+        }
+      }
+
+      if (style === "Beacon Fog") {
+        for (let i = 0; i < 240; i += 1) {
+          const x = Math.floor(random() * 100);
+          const y = Math.floor(random() * 100);
+          const c = random() > 0.5 ? palette.grid : palette.shade;
+          drawPixelRect(x, y, random() > 0.8 ? 2 : 1, 1, c);
+        }
+      }
+
+      if (style === "Mempool Rain") {
+        for (let i = 0; i < 38; i += 1) {
+          const x = Math.floor(random() * 100);
+          const y = Math.floor(random() * 100);
+          drawPixelRect(x, y, 1, Math.floor(5 + random() * 16), random() > 0.65 ? palette.accent : palette.grid);
+        }
+      }
+
+      if (style === "L2 Rings") {
+        ctx.strokeStyle = palette.grid;
+        ctx.lineWidth = 1;
+        for (let r = 12; r < 74; r += 12) {
+          ctx.strokeRect(50 - r / 2, 50 - r / 2, r, r);
+        }
+      }
+
+      if (style === "Archive Noise") {
+        for (let y = 0; y < 100; y += 2) {
+          const c = random() > 0.5 ? palette.grid : palette.bg;
+          drawPixelRect(0, y, 100, 1, c);
+        }
+        for (let i = 0; i < 130; i += 1) {
+          drawPixelRect(Math.floor(random() * 100), Math.floor(random() * 100), 1, 1, palette.accent);
+        }
+      }
+    }
+
+    function drawDiamond(random, palette, core) {
+      const cx = 50 + Math.floor((random() - 0.5) * 5);
+      const cy = 48 + Math.floor((random() - 0.5) * 5);
+      const scale = 1 + random() * 0.16;
+      const top = Math.round(cy - 36 * scale);
+      const mid = Math.round(cy);
+      const bottom = Math.round(cy + 39 * scale);
+      const left = Math.round(cx - 25 * scale);
+      const right = Math.round(cx + 25 * scale);
+
+      function poly(points, color) {
+        ctx.fillStyle = color;
+        ctx.beginPath();
+        ctx.moveTo(points[0][0], points[0][1]);
+        for (let i = 1; i < points.length; i += 1) ctx.lineTo(points[i][0], points[i][1]);
+        ctx.closePath();
+        ctx.fill();
+      }
+
+      poly([[cx, top], [left, mid], [cx, mid - 6]], palette.light);
+      poly([[cx, top], [cx, mid - 6], [right, mid]], palette.main);
+      poly([[left, mid], [cx, mid + 8], [cx, bottom]], palette.shade);
+      poly([[right, mid], [cx, mid + 8], [cx, bottom]], palette.main);
+
+      if (core === "Split Shard") {
+        drawPixelRect(cx - 2, top + 8, 4, bottom - top - 12, palette.bg);
+        drawPixelRect(cx - 1, top + 10, 2, bottom - top - 16, palette.accent);
+      }
+
+      if (core === "Staked Prism") {
+        for (let y = top + 10; y < bottom - 4; y += 8) {
+          drawPixelRect(cx - 18, y, 36, 2, palette.accent);
+        }
+      }
+
+      if (core === "Forked Crystal") {
+        poly([[left + 2, mid], [cx - 35, mid + 14], [cx - 12, mid + 9]], palette.accent);
+        poly([[right - 2, mid], [cx + 35, mid + 14], [cx + 12, mid + 9]], palette.accent);
+      }
+
+      if (core === "Genesis Rune") {
+        drawPixelRect(cx - 8, cy - 8, 16, 3, palette.bg);
+        drawPixelRect(cx - 8, cy + 5, 16, 3, palette.bg);
+        drawPixelRect(cx - 2, cy - 8, 4, 16, palette.accent);
+      }
+    }
+
+    function drawAura(random, palette, aura) {
+      if (aura === "None") return;
+      ctx.globalAlpha = 0.72;
+      if (aura === "Soft Glow") {
+        for (let i = 0; i < 40; i += 1) {
+          drawPixelRect(18 + random() * 64, 12 + random() * 78, 2, 2, palette.accent);
+        }
+      }
+      if (aura === "Sharp Halo") {
+        ctx.strokeStyle = palette.accent;
+        ctx.lineWidth = 2;
+        ctx.strokeRect(18, 16, 64, 68);
+      }
+      if (aura === "Gas Pulse") {
+        for (let i = 0; i < 26; i += 1) {
+          const size = 1 + Math.floor(random() * 3);
+          drawPixelRect(Math.floor(random() * 100), Math.floor(random() * 100), size, size, palette.accent);
+        }
+      }
+      if (aura === "Validator Ring") {
+        ctx.strokeStyle = palette.accent;
+        ctx.lineWidth = 1;
+        ctx.strokeRect(24, 20, 52, 60);
+        ctx.strokeRect(28, 24, 44, 52);
+      }
+      ctx.globalAlpha = 1;
+    }
+
+    function makeMetadata(seedText) {
+      const seed = hashString(seedText);
+      const random = mulberry32(seed);
+      const tokenNumber = 1 + Math.floor(random() * collectionSize);
+      const palette = pick(palettes, random);
+      const background = pick(backgrounds, random);
+      const core = pick(cores, random);
+      const aura = pick(auras, random);
+      const rarity = pick(rarities, random);
+      const gasMood = ["Low Gas", "Base Fee Spike", "MEV Shadow", "Finalized", "Ultra Sound"][Math.floor(random() * 5)];
+
+      return {
+        name: `CodexMint Pixel #${String(tokenNumber).padStart(4, "0")}`,
+        description: "A locally generated 100x100 pixel Ethereum-themed NFT draft for a 10,000 item collection.",
+        chain: "Ethereum",
+        collection_size: collectionSize,
+        token_id: tokenNumber,
+        seed: seedText,
+        image_pixels: "100x100",
+        attributes: [
+          { trait_type: "Palette", value: palette.name },
+          { trait_type: "Background", value: background },
+          { trait_type: "Core", value: core },
+          { trait_type: "Aura", value: aura },
+          { trait_type: "Gas Mood", value: gasMood },
+          { trait_type: "Rarity", value: rarity }
+        ],
+        _render: { palette, background, core, aura, rarity, gasMood, seed }
+      };
+    }
+
+    function renderTraits(metadata) {
+      traitsEl.innerHTML = "";
+      metadata.attributes.forEach((trait) => {
+        const item = document.createElement("div");
+        item.className = "trait";
+        item.innerHTML = `<span>${trait.trait_type}</span><b>${trait.value}</b>`;
+        traitsEl.appendChild(item);
+      });
+    }
+
+    function generate() {
+      const typedSeed = seedInput.value.trim();
+      const seedText = typedSeed || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
+      seedInput.value = seedText;
+      const metadata = makeMetadata(seedText);
+      const render = metadata._render;
+      const random = mulberry32(render.seed);
+
+      drawBackground(random, render.palette, render.background);
+      drawAura(random, render.palette, render.aura);
+      drawDiamond(random, render.palette, render.core);
+
+      currentMetadata = { ...metadata };
+      delete currentMetadata._render;
+      tokenName.textContent = metadata.name;
+      tokenId.textContent = `Token ${metadata.token_id} / ${collectionSize}`;
+      renderTraits(metadata);
+      metadataEl.textContent = JSON.stringify(currentMetadata, null, 2);
+      statusEl.innerHTML = `<span class="ok">Generated locally.</span> This art is not minted yet. Use the PNG and JSON as draft metadata for an Ethereum NFT workflow.`;
+    }
+
+    async function connectWallet() {
+      if (!window.ethereum) {
+        statusEl.innerHTML = `<span class="warn">No injected wallet found.</span> Open this page in a browser with MetaMask or another Ethereum wallet.`;
+        return;
+      }
+
+      try {
+        const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
+        const chainId = await window.ethereum.request({ method: "eth_chainId" });
+        const short = accounts[0] ? `${accounts[0].slice(0, 6)}...${accounts[0].slice(-4)}` : "connected";
+        const chainText = chainId === "0x1" ? "Ethereum mainnet" : `Chain ${chainId}`;
+        chainStatus.textContent = `${short} on ${chainText}`;
+        statusEl.innerHTML = chainId === "0x1"
+          ? `<span class="ok">Wallet connected on Ethereum.</span> This page still only generates local NFT drafts.`
+          : `<span class="warn">Wallet connected, but not Ethereum mainnet.</span> Current chain: ${chainId}.`;
+      } catch (error) {
+        statusEl.innerHTML = `<span class="warn">Wallet connection rejected.</span> ${error.message || "Try again from your wallet."}`;
+      }
+    }
+
