      min-width: 0;
    }

    .mark {
      width: 42px;
      height: 42px;
      display: grid;
      place-items: center;
      border: 1px solid rgba(121, 242, 192, 0.45);
      background: linear-gradient(180deg, rgba(121, 242, 192, 0.16), rgba(138, 180, 255, 0.08));
      box-shadow: 0 0 28px rgba(121, 242, 192, 0.18);
    }

    .mark svg {
      width: 26px;
      height: 26px;
    }

    h1 {
      margin: 0;
      font-size: clamp(24px, 3vw, 42px);
      line-height: 1;
      letter-spacing: 0;
    }

    .sub {
      margin: 7px 0 0;
      color: var(--muted);
      font-size: 14px;
      line-height: 1.5;
    }

    .chain-pill {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 13px;
      border: 1px solid var(--line);
      background: rgba(17, 21, 32, 0.78);
      color: var(--muted);
      white-space: nowrap;
    }

    .dot {
      width: 9px;
      height: 9px;
      background: var(--accent);
      box-shadow: 0 0 18px var(--accent);
    }

    main {
      display: grid;
      grid-template-columns: minmax(300px, 540px) 1fr;
      gap: 22px;
      align-items: stretch;
    }

    .stage,
    .panel {
      border: 1px solid var(--line);
      background: rgba(17, 21, 32, 0.78);
      backdrop-filter: blur(14px);
    }

    .stage {
      padding: 18px;
    }

    .canvas-wrap {
      position: relative;
      width: 100%;
      aspect-ratio: 1;
      background:
        linear-gradient(45deg, rgba(255, 255, 255, 0.045) 25%, transparent 25%),
        linear-gradient(-45deg, rgba(255, 255, 255, 0.045) 25%, transparent 25%),
        linear-gradient(45deg, transparent 75%, rgba(255, 255, 255, 0.045) 75%),
        linear-gradient(-45deg, transparent 75%, rgba(255, 255, 255, 0.045) 75%);
      background-size: 22px 22px;
      background-position: 0 0, 0 11px, 11px -11px, -11px 0;
      border: 1px solid rgba(255, 255, 255, 0.1);
      overflow: hidden;
    }

    canvas {
      width: 100%;
      height: 100%;
      display: block;
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }

    .token-strip {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 12px;
      align-items: center;
      margin-top: 14px;
    }

    .token-name {
      margin: 0;
      font-size: 20px;
      line-height: 1.2;
      overflow-wrap: anywhere;
    }

    .token-id {
      color: var(--accent);
      font-family: "SFMono-Regular", Consolas, monospace;
      font-size: 13px;
      border: 1px solid rgba(121, 242, 192, 0.32);
      padding: 8px 10px;
      background: rgba(121, 242, 192, 0.08);
    }

    .panel {
      display: flex;
      flex-direction: column;
      min-height: 100%;
    }

    .panel-section {
      padding: 18px;
      border-bottom: 1px solid var(--line);
    }

