      const bearish = style === "Bearish Chop";
      let lastY = bullish ? 12 : bearish ? 5 : 9;
      for (let x = 1; x < 15; x += 3) {
        const drift = bullish ? -1 : bearish ? 1 : 0;
        const close = Math.max(2, Math.min(13, lastY + drift + Math.floor((random() - 0.5) * 4)));
        const top = Math.min(lastY, close);
        const bottom = Math.max(lastY, close);
        const up = close <= lastY;
        drawPixelRect(x + 1, Math.max(1, top - 1), 1, Math.min(14, bottom + 1) - Math.max(1, top - 1) + 1, palette.grid);
        drawPixelRect(x, top, 2, Math.max(1, bottom - top + 1), up ? palette.spark : "#ff356a");
        lastY = close;
      }

      if (style === "Holo Orderbook") {
        drawPixelRect(0, 2, 4, 1, palette.accent);
        drawPixelRect(12, 3, 4, 1, palette.spark);
        drawPixelRect(0, 13, 5, 1, "#ff356a");
        drawPixelRect(11, 12, 5, 1, palette.accent);
      }

      if (style === "Volatility Grid" || style === "Glitch Chart") {
        for (let i = 0; i < 8; i += 1) {
          drawPixelRect(Math.floor(random() * 16), Math.floor(random() * 16), 1 + Math.floor(random() * 2), 1, random() > 0.5 ? palette.accent : palette.spark);
        }
      }

      drawEthMini(1, 1, palette.accent);
      if (random() > 0.45) drawEthMini(13, 13, palette.spark);
    }

    function drawEthMini(x, y, color) {
      drawPixelRect(x + 1, y, 1, 1, color);
      drawPixelRect(x, y + 1, 3, 1, color);
      drawPixelRect(x + 1, y + 2, 1, 1, color);
    }

    function drawLobster(random, palette, body, claws, eyes, marks) {
      const shell = palette.shell;
      const shade = palette.shade;
      const light = palette.light;
      const accent = palette.accent;
      const spark = palette.spark;

      const chunky = body === "Chunky Shell";
      const longTail = body === "Long Tail";
      const armored = body === "Armored Lobster" || body === "Chrome Molt";
      const needle = claws === "Needle Claws";
      const megaLeft = claws === "Mega Left Claw";
      const megaRight = claws === "Mega Right Claw";
      const asym = claws === "Asymmetric Claws";

      drawPixelRect(6, 5, chunky ? 5 : 4, 5, shell);
      drawPixelRect(6, 5, chunky ? 5 : 4, 1, light);
      drawPixelRect(6, 9, chunky ? 5 : 4, 1, shade);
      drawPixelRect(7, 10, 3, longTail ? 3 : 2, shell);
      drawPixelRect(6, 12, 5, 1, shade);
      drawPixelRect(7, 13, 3, 1, shell);
      drawPixelRect(6, 14, 5, 1, shade);

      drawPixelRect(6, 4, 1, 1, shell);
      drawPixelRect(9, 4, 1, 1, shell);
      drawPixelRect(5, 3, 1, 1, shell);
      drawPixelRect(10, 3, 1, 1, shell);
      drawPixelRect(4, 2, 1, 1, accent);
      drawPixelRect(11, 2, 1, 1, accent);

      drawPixelRect(5, 5, 1, 1, eyeColor(eyes, palette));
      drawPixelRect(10, 5, 1, 1, eyeColor(eyes, palette));
      if (eyes === "Magenta Visor") drawPixelRect(5, 5, 6, 1, "#ff3df2");
      if (eyes === "Laser Eyes") {
        drawPixelRect(2, 5, 3, 1, "#ff356a");
        drawPixelRect(11, 5, 3, 1, "#ff356a");
      }

      drawPixelRect(4, 7, 2, 2, shade);
      drawPixelRect(10, 7, 2, 2, shade);
      drawPixelRect(3, 8, 2, 1, shell);
      drawPixelRect(12, 8, 2, 1, shell);
      drawPixelRect(2, 10, 2, 1, shell);
      drawPixelRect(12, 10, 2, 1, shell);

      drawClaw16(2, 3, -1, palette, needle, megaLeft || asym);
      drawClaw16(13, 3, 1, palette, needle, megaRight);

      if (armored) {
        drawPixelRect(6, 7, chunky ? 5 : 4, 1, accent);
        drawPixelRect(6, 9, chunky ? 5 : 4, 1, spark);
      }
      if (marks === "Circuit Stripes") {
        drawPixelRect(7, 6, 2, 1, spark);
        drawPixelRect(7, 8, 2, 1, spark);
      }
      if (marks === "Dorsal Spikes") {
        drawPixelRect(8, 4, 1, 1, spark);
        drawPixelRect(8, 7, 1, 1, spark);
        drawPixelRect(8, 10, 1, 1, spark);
      }
      if (marks === "Market Scars") {
        drawPixelRect(7, 7, 2, 1, palette.bg);
        drawPixelRect(9, 9, 1, 1, palette.bg);
      }
      if (marks === "ETH Barnacles") {
        drawEthMini(6, 7, accent);
        drawEthMini(9, 10, spark);
      }
    }

    function drawClaw16(x, y, dir, palette, needle, mega) {
      const shell = palette.shell;
      const shade = palette.shade;
      const light = palette.light;
      const size = mega ? 3 : 2;
      const left = dir < 0 ? x - size + 1 : x;
      drawPixelRect(left, y, size, 2, shell);
      drawPixelRect(left, y + 2, size, 1, shade);
      if (needle) {
        drawPixelRect(dir < 0 ? left - 2 : left + size, y, 2, 1, light);
        drawPixelRect(dir < 0 ? left - 1 : left + size, y + 2, 1, 1, light);
      } else {
        drawPixelRect(dir < 0 ? left - 1 : left + size, y - 1, 2, 1, shell);
        drawPixelRect(dir < 0 ? left - 1 : left + size, y + 2, 2, 1, shade);
      }
    }

    function eyeColor(eyes, palette) {
      if (eyes === "Magenta Visor") return "#ff3df2";
      if (eyes === "Acid Dots") return "#b5ff00";
      if (eyes === "Sleepy Pixels") return palette.shade;
      return palette.accent;
    }

    function makeMetadata(seedText) {
      const seed = hashString(seedText);
      const random = mulberry32(seed);
      const tokenNumber = 1 + Math.floor(random() * collectionSize);
      const palette = pick(palettes, random);
      const background = pick(backgrounds, random);
      const body = pick(lobsterBodies, random);
      const claws = pick(clawTypes, random);
      const eyes = pick(eyeTypes, random);
      const marks = pick(shellMarks, random);
      const rarity = pick(rarities, random);
      const marketMood = ["Bullish Snap", "Bearish Pinch", "Sideways Molt", "Finalized Catch", "Ultra Sound Claw"][Math.floor(random() * 5)];

      return {
        name: `Pixel Lobster #${String(tokenNumber).padStart(4, "0")}`,
        description: "A locally generated 16x16 cyber pixel lobster NFT draft based on a reference lobster image, with an Ethereum chart backdrop.",
        chain: "Ethereum",
        collection_size: collectionSize,
        token_id: tokenNumber,
        seed: seedText,
        image_pixels: "16x16",
        attributes: [
          { trait_type: "Palette", value: palette.name },
          { trait_type: "ETH Chart", value: background },
          { trait_type: "Lobster Body", value: body },
          { trait_type: "Claws", value: claws },
          { trait_type: "Eyes", value: eyes },
          { trait_type: "Shell Marks", value: marks },
          { trait_type: "Market Mood", value: marketMood },
          { trait_type: "Rarity", value: rarity }
        ],
        _render: { palette, background, body, claws, eyes, marks, rarity, marketMood, seed }
      };
    }

    function renderTraits(metadata) {
      traitsEl.innerHTML = "";
      metadata.attributes.forEach((trait) => {
        const item = document.createElement("div");
        item.className = "trait";
        item.innerHTML = `<span>${trait.trait_type}</span><b>${trait.value}</b>`;
        traitsEl.appendChild(item);
      });
    }

    function createRandomSeed() {
      const entropy = crypto && crypto.getRandomValues
        ? crypto.getRandomValues(new Uint32Array(4)).join("-")
        : Math.random().toString(16).slice(2);
      return `${Date.now()}-${entropy}`;
    }

    function generate(options = {}) {
      const shouldUseTypedSeed = options.useTypedSeed === true;
      const typedSeed = seedInput.value.trim();
      const seedText = shouldUseTypedSeed && typedSeed ? typedSeed : createRandomSeed();
      seedInput.value = seedText;
      const metadata = makeMetadata(seedText);
      const render = metadata._render;
      const random = mulberry32(render.seed);

      drawBackground(random, render.palette, render.background);
      drawLobster(random, render.palette, render.body, render.claws, render.eyes, render.marks);

      currentMetadata = { ...metadata };
      delete currentMetadata._render;
      tokenName.textContent = metadata.name;
      tokenId.textContent = `Token ${metadata.token_id} / ${collectionSize}`;
      renderTraits(metadata);
      metadataEl.textContent = JSON.stringify(currentMetadata, null, 2);
      statusEl.innerHTML = `<span class="ok">Generated locally.</span> This lobster art is not minted yet. Use the PNG and JSON as draft metadata for an Ethereum NFT workflow.`;
    }

    async function connectWallet() {
      if (!window.ethereum) {
        statusEl.innerHTML = `<span class="warn">No injected wallet found.</span> Open this page in a browser with MetaMask or another Ethereum wallet.`;
        return;
      }

      try {
        const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
        const chainId = await window.ethereum.request({ method: "eth_chainId" });
        const short = accounts[0] ? `${accounts[0].slice(0, 6)}...${accounts[0].slice(-4)}` : "connected";
        const chainText = chainId === "0x1" ? "Ethereum mainnet" : `Chain ${chainId}`;
        chainStatus.textContent = `${short} on ${chainText}`;
        statusEl.innerHTML = chainId === "0x1"
          ? `<span class="ok">Wallet connected on Ethereum.</span> This page still only generates local NFT drafts.`
          : `<span class="warn">Wallet connected, but not Ethereum mainnet.</span> Current chain: ${chainId}.`;
      } catch (error) {
        statusEl.innerHTML = `<span class="warn">Wallet connection rejected.</span> ${error.message || "Try again from your wallet."}`;
      }
    }

    function downloadPng() {
      const link = document.createElement("a");
      const id = currentMetadata ? String(currentMetadata.token_id).padStart(4, "0") : "0000";
      link.download = `pixel-lobster-${id}.png`;
      link.href = canvas.toDataURL("image/png");
      link.click();
    }

    generateBtn.addEventListener("click", () => generate());
    connectBtn.addEventListener("click", connectWallet);
    downloadBtn.addEventListener("click", downloadPng);
    seedInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") generate({ useTypedSeed: true });
    });

    generate();
  </script>
</body>
</html>

